package com.kuaixietech.storage;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import com.kuaixietech.integration.*;
import com.kuaixietech.security.DomainAccessGuard;
import java.net.URI;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockMultipartFile;
class PrivateStorageTest {
 final String user="123e4567-e89b-42d3-a456-426614174000",key="private/123e4567-e89b-42d3-a456-426614174000/223e4567-e89b-42d3-a456-426614174000";
 PrivateObjectStorage.Binding oss(){return new PrivateObjectStorage.Binding("aliyun","bucket",Map.of("endpoint","https://oss-cn-hangzhou.aliyuncs.com","access_key_id","fake-id","access_key_secret","fake-secret"));}
 IntegrationHttp http(){var h=mock(IntegrationHttp.class);when(h.endpoint(anyString(),eq(true))).thenAnswer(c->URI.create(c.getArgument(0)));return h;}
 @Test void ossUploadForcesPrivateAclAndSignedContentMd5(){var s=new PrivateObjectStorage(mock(IntegrationConfiguration.class),http());var r=s.signed(oss(),"PUT",key,"application/pdf","md5",new byte[]{1},Instant.parse("2025-01-01T00:00:00Z"));assertEquals("private",r.headers().firstValue("x-oss-object-acl").orElseThrow());assertEquals("md5",r.headers().firstValue("Content-MD5").orElseThrow());assertEquals("OSS fake-id:Br2qQtP3SPSAVRT6DZn3s71dSdo=",r.headers().firstValue("Authorization").orElseThrow());assertEquals("Wed, 01 Jan 2025 00:00:00 GMT",r.headers().firstValue("Date").orElseThrow());assertEquals("bucket.oss-cn-hangzhou.aliyuncs.com",r.uri().getHost());}
 @Test void cosUsesV5CanonicalHeadersAndPrivateAcl(){var b=new PrivateObjectStorage.Binding("tencent","bucket-12345678",Map.of("region","ap-guangzhou","secret_id","fake-id","secret_key","fake-secret"));var r=new PrivateObjectStorage(mock(IntegrationConfiguration.class),http()).signed(b,"PUT",key,"image/png","md5",new byte[]{1},Instant.parse("2025-01-01T00:00:00Z"));assertEquals("private",r.headers().firstValue("x-cos-acl").orElseThrow());String auth=r.headers().firstValue("Authorization").orElseThrow();assertTrue(auth.contains("q-header-list=content-md5;content-type;host;x-cos-acl"));assertTrue(auth.contains("q-sign-time=1735689570;1735689900"));assertTrue(auth.endsWith("q-signature=cbf17f2f2816258f8b15380218b8cc7d6086a181"));}
 @Test void untrustedEndpointsAndObjectPathsAreRejected(){var s=new PrivateObjectStorage(mock(IntegrationConfiguration.class),http());var b=new PrivateObjectStorage.Binding("aliyun","bucket",Map.of("endpoint","https://evil.example","access_key_id","fake","access_key_secret","fake"));assertThrows(IllegalArgumentException.class,()->s.signed(b,"GET",key,"","",null,Instant.now()));assertThrows(IllegalArgumentException.class,()->s.signed(oss(),"GET","../other-user","","",null,Instant.now()));}
 @Test void failedObjectReceiptCannotCreateFileMetadata(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);when(guard.requireActiveProfile()).thenReturn(user);var storage=mock(PrivateObjectStorage.class);when(storage.active()).thenReturn(oss());doThrow(new IllegalStateException("unconfirmed")).when(storage).put(any(),any(),any(),any());var service=new PrivateUploads(db,guard,storage);assertThrows(IllegalStateException.class,()->service.upload(new MockMultipartFile("file","license.pdf","application/pdf","%PDF-1.7".getBytes()),"store_license"));verifyNoInteractions(db);}
 @Test void invalidOrExecutableFilesNeverReachStorage(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);when(guard.requireActiveProfile()).thenReturn(user);var storage=mock(PrivateObjectStorage.class);var service=new PrivateUploads(db,guard,storage);assertThrows(IllegalArgumentException.class,()->service.upload(new MockMultipartFile("file","image.png","image/png","<html>fake image</html>".getBytes()),"store_license"));verifyNoInteractions(db,storage);}
 @Test void uploadAcknowledgementStoresHashAndOwnedPrivateKey(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);when(guard.requireActiveProfile()).thenReturn(user);var storage=mock(PrivateObjectStorage.class);when(storage.active()).thenReturn(oss());when(storage.reference(any(),anyString())).thenAnswer(c->"v1:0:aliyun://bucket/"+c.getArgument(1));when(db.update(anyString(),any(Object[].class))).thenReturn(1);var result=new PrivateUploads(db,guard,storage).upload(new MockMultipartFile("file","license.pdf","application/pdf","%PDF-1.7".getBytes()),"store_license");assertEquals("application/pdf",result.get("contentType"));assertTrue(result.get("sha256").toString().matches("[a-f0-9]{64}"));verify(db).update(startsWith("INSERT INTO t_community_uploads"),any(),eq(user),eq("document"),startsWith("v1:0:aliyun://bucket/private/"+user+"/"),eq("application/pdf"),eq("store_license"),any(),eq(8),eq("license.pdf"));}
 @Test void foreignDownloadNeedsAdminAndNeverLeaksStorageCredentials(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);when(guard.requireActiveProfile()).thenReturn("other");when(guard.requireAdmin()).thenThrow(new SecurityException());when(db.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(Map.of("user_id",user,"kind","document","storage_key","aliyun://bucket/"+key)));var storage=mock(PrivateObjectStorage.class);assertThrows(SecurityException.class,()->new PrivateUploads(db,guard,storage).download("id"));verifyNoInteractions(storage);}
 @Test void downloadedBytesMustMatchOriginalDigest(){var db=mock(JdbcTemplate.class);var guard=mock(DomainAccessGuard.class);when(guard.requireActiveProfile()).thenReturn(user);when(db.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(Map.of("user_id",user,"kind","document","storage_key","aliyun://bucket/"+key,"sha256","0".repeat(64),"byte_size",8)));var storage=mock(PrivateObjectStorage.class);when(storage.get(any(),anyInt())).thenReturn("%PDF-1.7".getBytes());assertThrows(IllegalStateException.class,()->new PrivateUploads(db,guard,storage).download("id"));}
 @Test void bodyMagicBeatsClientMimeHeader(){assertEquals("application/pdf",PrivateUploads.mime("%PDF-1.7".getBytes()));assertThrows(IllegalArgumentException.class,()->PrivateUploads.mime(new byte[]{1,2,3}));}
 @Test void versionedObjectReadUsesPinnedLiveCredentials(){var config=mock(IntegrationConfiguration.class);var fields=new HashMap<>(oss().fields());fields.put("bucket","bucket");when(config.historicalLiveRuntime("aliyun","oss",7)).thenReturn(fields);var h=http();when(h.read(any(),eq(50))).thenReturn(new byte[]{1});var storage=new PrivateObjectStorage(config,h);var versioned=new HashMap<>(fields);versioned.put("_coupler_config_revision","7");String ref=storage.reference(new PrivateObjectStorage.Binding("aliyun","bucket",versioned),key);assertEquals("v1:7:aliyun://bucket/"+key,ref);assertArrayEquals(new byte[]{1},storage.get(ref,50));verify(config).historicalLiveRuntime("aliyun","oss",7);verify(config,never()).runtime(anyString(),anyString());}
 @Test void oldObjectDeleteDoesNotFollowCurrentEnvironment(){var config=mock(IntegrationConfiguration.class);var fields=new HashMap<>(oss().fields());fields.put("bucket","bucket");when(config.legacyLiveRuntime("aliyun","oss")).thenReturn(fields);var h=http();new PrivateObjectStorage(config,h).delete("aliyun://bucket/"+key);verify(h).delete(argThat(r->r.method().equals("DELETE")&&r.uri().getHost().equals("bucket.oss-cn-hangzhou.aliyuncs.com")));verify(config,never()).runtime(anyString(),anyString());}
 @Test void invalidReferenceAndChangedBucketNeverCallObjectProvider(){var config=mock(IntegrationConfiguration.class);when(config.historicalLiveRuntime("aliyun","oss",1)).thenReturn(Map.of("bucket","other"));var h=http();var storage=new PrivateObjectStorage(config,h);assertThrows(IllegalStateException.class,()->storage.get("v1:1:aliyun://bucket/"+key,50));assertThrows(IllegalArgumentException.class,()->storage.delete("aliyun://bucket/"+key+"?secret=x"));verifyNoInteractions(h);}
 @Test void productImagesRequireActualDecodableImage(){assertThrows(IllegalArgumentException.class,()->PrivateUploads.verifyImage("%PDF-1.7".getBytes(),"application/pdf"));assertThrows(IllegalArgumentException.class,()->PrivateUploads.verifyImage(new byte[]{(byte)0x89,80,78,71,13,10,26,10},"image/png"));}
 @Test void productImageMustDecodeAfterHeaderValidation()throws Exception{var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",out);byte[] png=out.toByteArray();assertDoesNotThrow(()->PrivateUploads.verifyImage(png,"image/png"));assertThrows(IllegalArgumentException.class,()->PrivateUploads.verifyImage(Arrays.copyOf(png,33),"image/png"));}
 @Test void newSelectedStorageDoesNotGetBlockedByOldRouting(){var config=mock(IntegrationConfiguration.class);when(config.couplerManaged("aliyun","oss")).thenReturn(true);when(config.runtime("aliyun","oss")).thenReturn(null);when(config.runtime("tencent","cos")).thenReturn(Map.of("bucket","bucket-12345678","secret_id","fake","secret_key","fake","region","ap-guangzhou"));assertEquals("tencent",new PrivateObjectStorage(config,http()).active().vendor());verify(config,never()).exists("platform","storage-routing");}
}
